"""Тест отдельной игры: запускается без Kairema, меню, игра, пауза, «Назад», нет ошибок страницы.
Запуск: python3 -I docs/tests/standalone.test.py   (нужны Playwright и Chromium)"""
import os
from playwright.sync_api import sync_playwright
UI = os.path.abspath(os.path.join(os.path.dirname(__file__), '../../app/src/main/assets/index.html'))
OK = 0; BAD = []
def check(n, c, i=''):
    global OK
    if c: OK += 1; print('ok  ', n)
    else: BAD.append(n); print('FAIL', n, i)
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={'width': 360, 'height': 780})
    errs = []; pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: m.type == 'error' and errs.append(m.text))
    pg.goto('file://' + UI); pg.wait_for_timeout(1200)
    check('меню открывается само: заголовок «Байт-прыгун»', pg.evaluate("(document.querySelector('.gm-hero h1')||{}).textContent") == 'Байт-прыгун')
    btns = pg.evaluate("[...document.querySelectorAll('.gm-b button')].map(x=>x.textContent.trim()).filter(Boolean)")
    check('в меню: Играть, Уровни, Бесконечный режим, Звук', len(btns) == 7 and 'Архив' in btns[4] and btns[0].startswith('Играть') and btns[1] == 'Уровни' and 'История' in btns, btns)
    pg.locator('.gm-b .gm-btn').first.click(); pg.wait_for_timeout(700)
    check('первый запуск: показан пролог', pg.evaluate("!!document.querySelector('.gm-story')") and 'Сеть Кайрема' in pg.evaluate("document.querySelector('.gm-st-t').textContent"))
    for _ in range(5): pg.locator('.gm-story .gm-btn.pri').click(); pg.wait_for_timeout(120)
    pg.wait_for_timeout(600)
    check('перед уровнем 1 показано вступление с кнопкой «Вперёд»', pg.evaluate("!!document.querySelector('.gm-intro')") and 'Пробуждение' in pg.evaluate("document.querySelector('.gm-intro h3').textContent"))
    pg.screenshot(path='/tmp/lv_intro.png'); pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(300)
    check('игра идёт: canvas есть, режим игры включён', pg.evaluate("!!document.querySelector('.gm-cv') && !!document.querySelector('.spg.gm')._inPlay"))
    check('5 сердец на уровень', pg.evaluate("document.querySelector('.spg.gm')._S().hearts") == 5)
    check('дверь есть в уровне', pg.evaluate("document.querySelector('.spg.gm')._S().items.some(i=>i.t==='door')"))
    for _ in range(8): pg.mouse.click(180, 400); pg.wait_for_timeout(200)
    check('«Назад» из игры: обработано, вернулись в меню', pg.evaluate("window.__back()") is True and pg.evaluate("!!document.querySelector('.gm-hero')"))
    check('«Назад» в меню: не обработано (оболочка закроет приложение)', pg.evaluate("window.__back()") is False)
    pg.locator('.gm-b .gm-btn').nth(1).click(); pg.wait_for_timeout(500)
    check('экран «Уровни» открывается', pg.evaluate("document.querySelectorAll('.gm-b button').length") >= 5)
    pg.locator(".gm-lt .gm-btn").click(); pg.wait_for_timeout(200)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent==='История').click()"); pg.wait_for_timeout(300)
    check('книга истории: 3 вводные, глава 1 и 9 закрытых, помехи и финалы закрыты', pg.evaluate("document.querySelectorAll('.gm-bk').length") == 15 and pg.evaluate("document.querySelectorAll('.gm-bk.lock').length") == 11)
    check('глава 2 закрыта до победы над боссом 1', pg.evaluate("[...document.querySelectorAll('.gm-bk.lock b')].some(b=>b.textContent.startsWith('2. Стек'))"))
    check('пролог больше не показывается второй раз', pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).seen") is True)
    # --- бой с боссом: анимация появления, джойстик, арена ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:10,st:{},b:0,best:0,boss:false,snd:0,bosses:0,seen:true,gl:true}))")
    pg.reload(); pg.wait_for_timeout(900)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(800)
    check('босс: показана анимация появления с именем', pg.evaluate("!!document.querySelector('.gm-intro')") and 'Потерянный Страж' in pg.evaluate("document.querySelector('.gm-intro h3').textContent"))
    pg.screenshot(path='/tmp/boss_intro.png')
    pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(500)
    check('босс 1: шахта (b12), 3 сердца, высота мира в три экрана, папки есть', pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();return S.arena&&S.b12&&S.hearts===3&&S.WH>S.H*2.5&&S.pl.length>=10})()"))
    pg.mouse.move(60, 600); pg.mouse.down(); pg.mouse.move(120, 600, steps=4); pg.wait_for_timeout(500)
    x1 = pg.evaluate("document.querySelector('.spg.gm')._S().p.x"); pg.mouse.up()
    check('джойстик двигает игрока вправо', x1 > 100, x1)
    pg.mouse.click(300, 600); pg.wait_for_timeout(2500); pg.screenshot(path='/tmp/boss_arena.png')
    # --- босс 6: кнопка «Отклонить» кликается, не вызывает прыжок ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:60,st:{},b:0,best:0,boss:false,snd:0,bosses:5,seen:true,gl:true}))")
    pg.reload(); pg.wait_for_timeout(900)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(800)
    check('босс 6: анимация появления с именем', 'Стиратель Реестра' in pg.evaluate("(document.querySelector('.gm-intro h3')||{}).textContent||''"))
    pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(400)
    pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();S.atk=99;S.fallT=99;S.wins.push({t:1.5,max:1.5,real:1,d:0})})()")
    xy = pg.evaluate("(()=>{const cv=document.querySelector('.gm-cv'),r=cv.getBoundingClientRect(),S=document.querySelector('.spg.gm')._S(),sc=Math.min(r.width/360,r.height/520);return[r.left+(S.W-62)*sc,r.top+(S.H-150)*sc]})()")
    pg.wait_for_timeout(100); pg.screenshot(path='/tmp/boss6_arena.png')
    pg.mouse.click(xy[0], xy[1]); pg.wait_for_timeout(150)
    check('босс 6: кнопка «Отклонить» убирает окно и копит заряд', pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();return S.chg===1&&S.wins.length===0})()"))
    check('босс 6: «Отклонить» не прыгает', pg.evaluate("document.querySelector('.spg.gm')._S().p.on===true"))
    # --- босс 10: «Ноль», мост, разговор и выбор финала ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:100,st:{},b:500,best:0,boss:false,snd:0,bosses:9,seen:true,gl:true}))")
    pg.reload(); pg.wait_for_timeout(900)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(800)
    check('босс 10: анимация появления с именем', 'Кернел' in pg.evaluate("(document.querySelector('.gm-intro h3')||{}).textContent||''"))
    pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(400)
    pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();S.boss.hp=20;S.hearts=99})()"); pg.wait_for_timeout(300)
    pg.screenshot(path='/tmp/boss10_nol.png')
    pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S(),q=S.pl[4];S.p.x=q.x+q.w-20;S.p.y=q.y-24;S.p.vy=0})()"); pg.wait_for_timeout(1200)
    check('босс 10: мост пройден, показан разговор Кернела', pg.evaluate("!!document.querySelector('.gm-story')") and 'Кернел' in pg.evaluate("document.querySelector('.gm-st-t').textContent"))
    for _ in range(4): pg.locator('.gm-story .gm-btn.pri').click(); pg.wait_for_timeout(120)
    names = pg.evaluate("[...document.querySelectorAll('.gm-b button')].map(x=>x.textContent.trim())")
    check('выбор финала: Перезагрузка и Открытая Сеть доступны, тайный и тёмный закрыты', 'Перезагрузка' in names and 'Открытая Сеть' in names and pg.evaluate("[...document.querySelectorAll('.gm-b button')].filter(x=>x.disabled).length")==2, names)
    pg.screenshot(path='/tmp/boss10_finale.png')
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.trim()==='Открытая Сеть').click()"); pg.wait_for_timeout(300)
    check('финал сохранён в прогрессе', pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).ends.includes('open')") and pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).bosses")==10)
    # --- босс 9: кнопка «Замри» удерживается ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:90,st:{},b:0,best:0,boss:false,snd:0,bosses:8,seen:true,gl:true}))")
    pg.reload(); pg.wait_for_timeout(900)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(800)
    pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(400)
    pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();S.boss.hp=60;S.atk=99;S.fallT=99})()")
    xy = pg.evaluate("(()=>{const cv=document.querySelector('.gm-cv'),r=cv.getBoundingClientRect(),S=document.querySelector('.spg.gm')._S(),sc=Math.min(r.width/360,r.height/520);return[r.left+(S.W-62)*sc,r.top+(S.H-150)*sc]})()")
    pg.mouse.move(xy[0], xy[1]); pg.mouse.down()
    pg.evaluate("document.querySelector('.spg.gm')._S().fzQ=1"); pg.wait_for_timeout(2700); pg.screenshot(path='/tmp/boss9_freeze.png'); pg.mouse.up(); pg.wait_for_timeout(100)
    check('босс 9: удержание кнопки «Замри» засчитано, сердца целы', pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();return S.fzS>=1&&S.hearts===3})()"))
    # --- Искра: картинка загружена, герой рисуется спрайтом, урон = выражение и частицы без отбрасывания (0.6.1) ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:10,st:{},b:0,best:0,boss:false,snd:0,bosses:0,seen:true,gl:true}))")
    pg.reload(); pg.wait_for_timeout(700)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(700)
    pg.locator('.gm-intro .gm-btn').click(); pg.wait_for_timeout(500)
    check('Искра: атлас загружен, рисуется картинкой', pg.evaluate("GameSpark.ready()") is True)
    px0 = pg.evaluate("document.querySelector('.spg.gm')._S().p.x")
    pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();S.atk=99;S.hearts--;S.lost++;S.p.inv=1.3})()"); pg.wait_for_timeout(120)
    check('урон: показано выражение «> <» и частицы', pg.evaluate("(()=>{const m=document.querySelector('.spg.gm')._S()._sp;return !!m&&m.parts.length>0})()"))
    check('урон: героя не отбросило и не уронило', abs(pg.evaluate("document.querySelector('.spg.gm')._S().p.x") - px0) < 1 and pg.evaluate("document.querySelector('.spg.gm')._S().p.on") is True)
    pg.evaluate("Game.setForm(2)"); pg.wait_for_timeout(200)
    check('эволюция: форма сохраняется и не ломает бой', pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).form") == 2 and pg.evaluate("!!document.querySelector('.gm-cv')"))
    pg.evaluate("Game.setForm(0)")
    # --- новый дизайн: уровни 1–19 открываются, фон рисуется, меню и выбор уровней без горизонтальной прокрутки (0.7.0) ---
    ok_lv = True
    for L in (1, 4, 8, 12, 16, 19):
        pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:%d,st:{},b:0,best:0,boss:false,snd:0,bosses:%d,seen:true,gl:true}))" % (L, 0 if L < 10 else 1))
        pg.reload(); pg.wait_for_timeout(500)
        pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Играть')).click()"); pg.wait_for_timeout(450)
        ok_lv = ok_lv and pg.evaluate("(()=>{const S=document.querySelector('.spg.gm')._S();return !!S&&S.L===%d})()" % L)
    check('уровни 1, 4, 8, 12, 16, 19: открываются с новым фоном', ok_lv)
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:24,st:{},b:0,best:0,boss:false,snd:0,bosses:1,seen:true,gl:false}))"); pg.reload(); pg.wait_for_timeout(500)
    pg.evaluate("[...document.querySelectorAll('.gm-b button')].find(x=>x.textContent.startsWith('Уровни')).click()"); pg.wait_for_timeout(400)
    check('выбор уровней: сетка 5 в ряд помещается в экран', pg.evaluate("(()=>{const b=document.querySelector('.gm-b'),g=document.querySelector('.gm-grid');return b.scrollWidth<=b.clientWidth+1&&getComputedStyle(g).gridTemplateColumns.split(' ').length===5})()"))
    # --- движок 2.0: три режима помех сохраняются, миграция старого сохранения ---
    pg.evaluate("localStorage.setItem('kairema.game.v1',JSON.stringify({u:3,st:{},b:0,best:0,boss:false,snd:false,bosses:0,seen:true,gl:true,lfs:[4,4,9]}))")
    pg.reload(); pg.wait_for_timeout(900)
    pg.evaluate("[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Помехи')).click()"); pg.wait_for_timeout(200)
    j = pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1'))")
    check('миграция: после первого сохранения версия 2, уровень, звук и список Потеряшек на месте', j['v'] == 2 and j['u'] == 3 and j['snd'] is False and j['lf'] == 2 and j['lfs'] == [4, 9], j)
    m1 = pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).mode")
    pg.evaluate("[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Помехи')).click()"); pg.wait_for_timeout(200)
    m2 = pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).mode")
    pg.evaluate("[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Помехи')).click()"); pg.wait_for_timeout(200)
    m3 = pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).mode")
    check('помехи: кнопка переключает полные → мягкие → выкл', (m1, m2, m3) == ('soft', 'off', 'full'), (m1, m2, m3))
    for _ in range(2):
        pg.evaluate("[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Помехи')).click()"); pg.wait_for_timeout(200)
    pg.reload(); pg.wait_for_timeout(900)
    check('баг исправлен: «помехи выкл» переживают перезапуск', pg.evaluate("JSON.parse(localStorage.getItem('kairema.game.v1')).mode") == 'off')
    check('нет внешних запросов и ошибок страницы', not errs, errs)
    b.close()
print('\nИТОГ: %d ок, %d провалов' % (OK, len(BAD)))
if BAD: print('Провалы:', BAD); raise SystemExit(1)
